64	// applyTokenBudget greedily keeps the ranked results whose cumulative estimated
65	// token cost stays within maxTokens, ALWAYS keeping at least the top result (a
66	// single over-budget top hit still returns something, not an empty list).
67	// Returns the kept prefix, how many were dropped, and the approximate token
68	// total of the kept set. maxTokens <= 0 is a no-op passthrough (dropped=0,
69	// approxTotal=0) so callers can invoke it unconditionally.
70	func applyTokenBudget(results []search.Result, maxTokens int) (kept []search.Result, dropped, approxTotal int) {
71		if maxTokens <= 0 || len(results) == 0 {
72			return results, 0, 0
73		}
74		used, n := 0, 0
75		for i := range results {
76			cost := resultTokens(results[i])
77			if n > 0 && used+cost > maxTokens {
78				break
79			}
80			used += cost
81			n++
82		}
83		return results[:n], len(results) - n, used

